DROP TABLE IF EXISTS catalog_meta;
CREATE TABLE catalog_meta(key TEXT PRIMARY KEY, value TEXT NOT NULL);
DROP TABLE IF EXISTS shows;
CREATE TABLE shows( show_id TEXT PRIMARY KEY, date TEXT NOT NULL, year INTEGER NOT NULL, month INTEGER NOT NULL, day INTEGER NOT NULL, era_id TEXT, venue TEXT, city TEXT, state TEXT, setlist_status TEXT NOT NULL, recording_count INTEGER NOT NULL, best_identifier TEXT, best_source_type TEXT, avg_rating REAL, total_reviews INTEGER NOT NULL, total_downloads INTEGER NOT NULL, cover_image_url TEXT );
DROP TABLE IF EXISTS show_images;
CREATE TABLE show_images( date TEXT NOT NULL, position INTEGER NOT NULL, kind TEXT NOT NULL, url TEXT NOT NULL, width INTEGER, height INTEGER, PRIMARY KEY(date, position) );
DROP TABLE IF EXISTS recordings;
CREATE TABLE recordings( identifier TEXT PRIMARY KEY, show_id TEXT NOT NULL REFERENCES shows(show_id), title TEXT, source_type TEXT NOT NULL, source_text TEXT, lineage TEXT, taper TEXT, avg_rating REAL, num_reviews INTEGER NOT NULL, downloads INTEGER NOT NULL, quality_score REAL NOT NULL );
DROP TABLE IF EXISTS recording_tracks;
CREATE TABLE recording_tracks( identifier TEXT PRIMARY KEY REFERENCES recordings(identifier), tracks_json TEXT NOT NULL );
DROP TABLE IF EXISTS setlist_entries;
CREATE TABLE setlist_entries( show_id TEXT NOT NULL REFERENCES shows(show_id), position INTEGER NOT NULL, set_label TEXT NOT NULL, song_key TEXT NOT NULL, song_title TEXT NOT NULL, segues_into_next INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(show_id, position) );
DROP TABLE IF EXISTS songs;
CREATE TABLE songs( song_key TEXT PRIMARY KEY, title TEXT NOT NULL, times_played INTEGER NOT NULL, first_played TEXT, last_played TEXT );
DROP TABLE IF EXISTS song_aliases;
CREATE TABLE song_aliases( variant_key TEXT PRIMARY KEY, canonical_key TEXT NOT NULL );
DROP TABLE IF EXISTS ai_digest;
CREATE TABLE ai_digest( show_id TEXT PRIMARY KEY REFERENCES shows(show_id), consensus_summary TEXT NOT NULL, standout_songs_json TEXT NOT NULL, sentiment TEXT NOT NULL, derived_rating REAL NOT NULL, rating_rationale TEXT NOT NULL, model TEXT NOT NULL, generated_at TEXT NOT NULL );
CREATE INDEX idx_shows_ymd ON shows(year, month, day);
CREATE INDEX idx_shows_monthday ON shows(month, day);
CREATE INDEX idx_shows_venue ON shows(venue);
CREATE INDEX idx_recordings_show ON recordings(show_id, quality_score DESC);
CREATE INDEX idx_setlist_song ON setlist_entries(song_key, show_id);
